      		SELECT /*selectMasterMpRqReqUserSelPop*/ 
       					DISTINCT USER_ID AS REQ_USER_ID
	            	  , USER_NAME_LOC AS REQ_USER_NAME
			FROM MIS_BUYER_MNG A, ICOMLUSR B    
		   WHERE A.YEAR=TO_CHAR(SYSDATE, 'YYYY')        
				AND A.BUYER = #{st_buyer}
				AND A.STATUS='C'        
				AND A.KEP_DEPT = #{st_kep_dept}        
				AND A.START_SCOPE <= #{st_agent_min_price}        
				AND A.END_SCOPE > #{st_agent_min_price}        
				AND B.USER_ID=A.KEP_USER_ID

