UPDATE KEPRQDT	/*saveCmpySend*/				
   SET ATOB_REMARK = #{ATOB_REMARK}
   		, AGENT_OPEN_FLAG = DECODE(#{AGENT_OPEN_FLAG},'1','Y','N')
   		, RFQ_KEP_USER = #{RFQ_KEP_USER}
 WHERE BUYER          = #{BUYER}
   AND QUOTATION_NO   = #{QUOTATION_NO}
   AND QUOTATION_SEQ  = #{QUOTATION_SEQ}
   AND REVISION       = #{REVISION}
   AND STATUS IN ('C','R')


UPDATE KEPRQDT	/*updateInitKETRQDT*/			   
  SET RECV_FLAG     = 'GS'	
WHERE BUYER         = #{BUYER}
  AND QUOTATION_NO  = #{QUOTATION_NO}
  AND QUOTATION_SEQ = #{QUOTATION_SEQ}
AND REVISION      = #{REVISION}

