			UPDATE KEPMGPDT         /*updateRcApprovalKEPMGPDT*/   
           SET STATUS = DECODE(PA_FLAG, 'N','A','Y','P')  
                 , CONFIRM_DATE = SYSDATE
                 , CONFIRM_USER_ID = #{USER_ID}
           WHERE BUYER = #{KEY_2}                                                                                                     
             AND PM_NO =  #{KEY_1}


/*updateMasterMpRqAfterItemChgReq*/
UPDATE KEPRQDT
SET	AFTER_CMS_REJECT_FLAG = #{AFTER_CMS_REJECT_YN},
	AFTER_ITEM_CHG_REQ_ID = #{AFTER_ITEM_CHG_REQ_ID},
	AFTER_ITEM_CHG_REQ_DATE = SYSDATE,
	AFTER_ITEM_CHG_REQ_NOTE = #{AFTER_ITEM_CHG_REQ_NOTE},
	AFTER_ITEM_MD_USER_ID ='',
	AFTER_ITEM_MD_DATE = '',
	AFTER_ITEM_CHG_REQ_IMAGE_KEY = #{AFTER_ITEM_CHG_REQ_IMAGE_KEY}
WHERE BUYER = #{BUYER}
AND QUOTATION_NO = #{QUOTATION_NO}
AND QUOTATION_SEQ = #{QUOTATION_SEQ}
AND REVISION = #{REVISION}
AND STATUS <> 'D'


/*updateMasterMpRqKepAfterItemMdReq*/
UPDATE KEP_AFTER_ITEM_MD_REQ 
   SET ITEM_MD_STATUS = 'O'
 WHERE BUYER = #{BUYER}  
   AND QUOTATION_NO = #{QUOTATION_NO}    
   AND QUOTATION_SEQ = #{QUOTATION_SEQ}    
   AND REVISION = #{REVISION} 
   AND ITEM_MD_REVISION = #{AFTER_ITEM_MD_REVISION}


UPDATE KEPRQDT /*updateMasterMpRqAfterItmCheSend*/
   SET AFTER_ITEM_MD_USER_ID = #{st_user_id}
   ,AFTER_ITEM_MD_DATE = SYSDATE
   ,AFTER_ITEM_CHG_REQ_IMAGE_KEY = NULL
   ,DELETE_SCHD_DATE = NULL
 WHERE BUYER = #{BUYER}
   AND QUOTATION_NO = #{QUOTATION_NO}    
   AND QUOTATION_SEQ = #{QUOTATION_SEQ}    
   AND REVISION = #{REVISION}
   AND STATUS <> 'D'


UPDATE KEP_AFTER_ITEM_MD_REQ /*updateMasterMpRqAfterItmMdSend*/
   SET ITEM_MD_USER_ID = #{st_user_id}
   ,ITEM_MD_DATE = SYSDATE
 WHERE BUYER = #{BUYER}
   AND QUOTATION_NO = #{QUOTATION_NO}    
   AND QUOTATION_SEQ = #{QUOTATION_SEQ}    
   AND REVISION = #{REVISION}
   AND ITEM_MD_REVISION = #{AFTER_ITEM_MD_REVISION}
   AND ITEM_MD_STATUS = 'C'

