/*selectMasterMpRqGplChk*/

	SELECT CASE
	        WHEN COUNT(*) = 0 THEN 'Y' -- GPL 아닌경우
	        WHEN SUM(CASE WHEN STATUS <> 'D' THEN 1 ELSE 0 END) > 0 THEN 'Y' -- GPL인데 사용 상태인 경우
	        ELSE 'N' -- 전부 삭제 상태인 경우
	        END DSS_CHK
	 FROM ICOMCQDT
	 WHERE BUYER ='KRGPLK0001'
	 AND BUYER_ITEM_NO = #{CMS_CATLG_ID}
	 AND AGENT = #{AGENT}
